package kanon

import (
	"fmt"
	"go/types"
	"maps"
	"slices"
	"strings"
)

// Lines that open every generated file.
const (
	// generatedHeader marks the file as generated, in the form that
	// go.dev/s/generatedcode specifies.
	generatedHeader = "// Code generated by kanon. DO NOT EDIT.\n"
	// sourceHeader precedes the base name of the source file.
	sourceHeader = "// source: "
)

// Suffixes that follow the name of a -type struct in the names of its view
// type and of the index type of the view.
const (
	viewSuffix  = "View"
	indexSuffix = "Index"
)

// codeFile returns the code file of u: the numbers lines, the version check,
// the interface assertions of the targets, the methods of each target, a
// view type and its index type per target when u.views is set, the
// ValidateKanon method of
// each value type, and the helpers that the code calls, in the order in
// which it first calls them.
func codeFile(u *unit) ([]byte, error) {
	e := &emitter{
		p:      u.printer(),
		prefix: u.prefix,
		names:  make(map[helperKey]string),
		words:  make(map[string]string),
		owners: make(map[string]string),
		cls: classifier{
			nested:    u.pkg.nested,
			generated: u.pkg.generated,
			validated: u.pkg.validated,
			pkg:       u.pkg.types,
			fset:      u.pkg.fset,
			inlines:   u.inlines,
			named:     make(map[string]*value),
			codecs:    make(map[string]*types.Named),
			lookup:    true,
		},
		generates:  u.pkg.generates,
		keyStructs: u.keyStructs,
		views:      make(map[types.Object]bool),
		keyTargets: make(map[string]*target),
		canonical:  u.canonical,
	}
	if u.views {
		for _, m := range u.targets {
			e.views[m.decl] = true
		}
	}
	markNilable(slices.Concat(u.targets, u.inlines.list))
	e.merging = mergingValues(slices.Concat(u.targets, u.inlines.list))
	rt := e.rt()
	e.line("")
	e.doc(fmt.Sprintf("The file compiles against a runtime that supports version %d of the generator.",
		generatorVersion))
	e.line("const (")
	e.line("_ = %sEnforceVersion(%d - %sMinVersion)", rt, generatorVersion, rt)
	e.line("_ = %sEnforceVersion(%sMaxVersion - %d)", rt, rt, generatorVersion)
	e.line(")")
	e.line("")
	if len(u.targets) > 0 {
		e.line("// The generated types implement kanon.Cloner.")
		e.line("var (")
		for _, m := range u.targets {
			typ := e.p.typ(m.typ)
			e.line("_ %sCloner[%s] = (*%s)(nil)", rt, typ, typ)
		}
		e.line(")")
		e.line("")
	}
	for _, m := range u.targets {
		e.sizeMethod(m)
		e.encodeMethods(m)
		e.decodeMethods(m)
		e.resetMethod(m)
		e.cloneMethods(m)
		if u.views {
			e.viewType(m)
		}
	}
	for _, vt := range u.values {
		e.validateMethod(vt)
	}
	e.helpers()
	if err := u.check(e); err != nil {
		return nil, err
	}
	var header strings.Builder
	header.WriteString(u.header())
	header.WriteByte('\n')
	for _, m := range u.numbered {
		header.WriteString(m.numbersLine())
		header.WriteByte('\n')
	}
	for _, l := range u.lists {
		header.WriteString(l.numbersLine())
		header.WriteByte('\n')
	}
	for _, line := range u.carried {
		header.WriteString(line)
		header.WriteByte('\n')
	}
	return e.p.source(header.String(), u.pkg.types.Name())
}

// check fails for a declaration of the package of u that breaks the code
// file that e wrote: a declaration named like a helper or a view type, one
// that shadows a predeclared identifier that the code uses, a type or a
// constant that the code refers to under the name of one of its locals,
// and a field or a method of a target named like a method that kanon
// generates.
func (u *unit) check(e *emitter) error {
	scope := u.pkg.types.Scope()
	names := slices.Sorted(maps.Values(e.names))
	if u.views {
		for _, m := range u.targets {
			names = append(names, m.name+viewSuffix, m.name+indexSuffix)
		}
	}
	for _, name := range names {
		if obj := scope.Lookup(name); obj != nil {
			return u.clash(obj, "the name of a declaration of the generated code")
		}
	}
	for _, name := range predeclaredNames() {
		if obj := scope.Lookup(name); obj != nil {
			return u.clash(obj, "a predeclared identifier that the generated code uses")
		}
	}
	for _, name := range localNames() {
		if e.p.refs[name] {
			return u.clash(scope.Lookup(name), "the name of a local variable of the generated code")
		}
	}
	for _, m := range u.targets {
		for _, name := range methodNames() {
			obj, index, _ := types.LookupFieldOrMethod(m.typ, true, m.decl.Pkg(), name)
			if obj != nil && len(index) == 1 {
				return m.fail(obj, fmt.Errorf("kanon: %s declares %s, which kanon generates", m.name, name))
			}
		}
	}
	return nil
}

// clash returns the error for the package-level declaration obj, whose name
// the generated code of u gives the role role.
func (u *unit) clash(obj types.Object, role string) error {
	return &sourceError{
		err:     fmt.Errorf("kanon: %s is %s: rename it", obj.Name(), role),
		pos:     u.pkg.fset.Position(obj.Pos()),
		subject: obj.Name(),
	}
}

// methodNames returns the names of the methods that a code file declares on
// each -type struct.
func methodNames() []string {
	return []string{
		appendBinaryName, cloneKanonName, cloneMethod, decodeKanonName, decodeMethod, encodeKanonName,
		encodeMethod, fieldsMethod, marshalBinaryName, mergeKanonName, mergeMethod, resetName, sizeKanonName,
		unmarshalBinaryName,
	}
}

// localNames returns the names that the generated code gives its
// parameters, locals and local type aliases. No import takes one of them,
// and the generation fails when the code refers to a type or a constant of
// the package under one of them.
func localNames() []string {
	return []string{
		"a", "all", "arr", "at", "av", "b", "buf", "bv", "c", "ck", "collect", "cv", "data", "depth", "dst", "ea", "eb",
		"enc",
		"end", "err", "free", "freeKeys", fromName, "held", "i", "im", "ix", "k", "keys", "l", "last", locParam, "m",
		membersName, "mk",
		"mv",
		mergeParam, "n", "na", "nb", numParam, "off", "ok", "opts", "out", "pair", "pairs", prevKeyName, "present",
		priorName, "re", "s",
		"sa", "sb",
		"scratch", "seen", "size", "skipped", "slab", "src", "t", "tag", "u", "used", "v", "w", "x", "zero",
	}
}

// predeclaredNames returns the predeclared identifiers that the generated
// code uses. The generation fails when the package declares one of them,
// which would shadow it.
func predeclaredNames() []string {
	return []string{
		"any", "append", "bool", "byte", "cap", "clear", "complex", "complex128", "complex64", "copy", "error",
		falseName, "float32", "float64", "imag", "int", "int16", "int32", "int64", "int8", "len", "make", "new",
		nilName, "real", "string", trueName, "uint", "uint16", "uint32", "uint64", "uint8", "uintptr",
	}
}
